const b = $json.body || {};
const PASS = '5820090e120504a5d4ef1fff45096246';
const fail = (httpCode, body) => [{ json: { httpCode, body } }];
if (b.key !== PASS) return fail(401, { error: 'unauthorized', message: '접속 코드가 올바르지 않습니다.' });
const hh = (typeof $helpers !== 'undefined' && $helpers && $helpers.httpRequest) || (this.helpers && this.helpers.httpRequest);
if (!hh) return fail(500, { error: 'no-http-helper' });
const call = (path, payload) => hh({ method: 'POST', url: 'http://127.0.0.1:11434' + path, body: payload, headers: { 'Content-Type': 'application/json' }, json: true });
try {
  if (b.ping) {
    await call('/api/generate', { model: 'qwen3:14b', prompt: '핑', think: false, stream: false, keep_alive: '3m', options: { num_predict: 1 } });
    return [{ json: { httpCode: 200, body: { ok: true } } }];
  }
  const payload = { model: b.model || 'qwen3:14b', messages: b.messages || [], stream: false, think: false, keep_alive: '3m', options: { num_ctx: 8192, temperature: 0.1 } };  // 2026-09-25 라우팅 결정성(복합명령/인자 안정화 실측)
  if (b.tools && b.tools.length) payload.tools = b.tools;
  const r = await call('/api/chat', payload);
  return [{ json: { httpCode: 200, body: { message: r.message } } }];
} catch (e) {
  return fail(502, { error: 'gateway', message: String(e && e.message || e).slice(0, 200) });
}

